-- Remove generic search/map pages from the official venue website field.
-- Source links remain intact in source_url; map links are generated by the app.
UPDATE public.places
SET website_url = '',
    updated_at = now()
WHERE website_url ~* '^https?://(www\.)?google\.com/(search|maps)(/|[?#]|$)'
   OR website_url ~* '^https?://([a-z0-9-]+\.)?yandex\.(by|com|ru)/maps(/|[?#]|$)';
